  MDEEventT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(MDEEventT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<MDEEvent> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const MDEEventT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
